import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z } from "npm:zod@^3.25.76";
var list_menu_default = defineTool2({
  name: "list_menu",
  title: "List menu items",
  description: "List menu items with prices in INR. Optionally filter by a category label (case-insensitive, e.g. 'Veg Starters').",
  inputSchema: {
    category: z.string().trim().optional().describe("Optional category label to filter by.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category }) => {
    const filter = category?.toLowerCase();
    const cats = filter ? menuCategories.filter((c) => c.label.toLowerCase() === filter) : menuCategories;
    if (filter && cats.length === 0) {
      return {
        content: [{ type: "text", text: `No category matching "${category}".` }],
        isError: true
      };
    }
    const lines = [];
    const structured = cats.map((c) => {
      lines.push(`
## ${c.label}`);
      for (const it of c.items) lines.push(`- ${it.name} \u2014 \u20B9${it.price}`);
      return { category: c.label, items: c.items };
    });
    return {
      content: [{ type: "text", text: lines.join("\n").trim() }],
      structuredContent: { categories: structured }
    };
  }
});

