import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z2 } from "npm:zod@^3.25.76";
var search_menu_default = defineTool3({
  name: "search_menu",
  title: "Search menu",
  description: "Search menu items by keyword in the dish name. Returns matches with price and category.",
  inputSchema: {
    query: z2.string().trim().min(1).describe("Keyword to match against dish names."),
    limit: z2.number().int().min(1).max(50).default(20)
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, limit }) => {
    const q = query.toLowerCase();
    const matches = [];
    for (const c of menuCategories) {
      for (const it of c.items) {
        if (it.name.toLowerCase().includes(q)) {
          matches.push({ name: it.name, price: it.price, category: c.label });
          if (matches.length >= limit) break;
        }
      }
      if (matches.length >= limit) break;
    }
    const text = matches.length ? matches.map((m) => `- ${m.name} \u2014 \u20B9${m.price} (${m.category})`).join("\n") : `No dishes matching "${query}".`;
    return {
      content: [{ type: "text", text }],
      structuredContent: { matches }
    };
  }
});

